<?php
require_once __DIR__.'/ali-characteristics.php';
function aliKnowledgeCanEdit($db,$q){
 $pos=$q->getAttribute('ali_pos')?:[];
 if(!empty($pos['admin'])||!empty($pos['write']))return true;
 $role=$db->prepare("SELECT p.UsuarioPerfil FROM Seg_Usuario u JOIN Seg_UsuarioPerfil p ON p.IdUsuarioPerfil=u.IdUsuarioPerfil WHERE LOWER(u.Usuario)=LOWER(?) AND (u.Anulado IS NULL OR u.Anulado<>1) LIMIT 1");$role->execute([$q->getAttribute('ali_user')]);if(in_array(mb_strtolower(trim((string)$role->fetchColumn())),['vendedor','vendedores'],true))return true;
 $s=$db->prepare("SELECT 1 FROM Seg_Usuario u JOIN Seg_UsuarioModulo_has_UsuarioPerfil p ON p.IdUsuarioPerfil=u.IdUsuarioPerfil JOIN Seg_UsuarioModulo m ON m.IdUsuarioModulo=p.IdUsuarioModulo WHERE LOWER(u.Usuario)=LOWER(?) AND (u.Anulado IS NULL OR u.Anulado<>1) AND (p.Anulado IS NULL OR p.Anulado<>1) AND LOWER(m.UsuarioModulo)='gen_productoform.php' AND CAST(p.Lectura AS UNSIGNED)=1 AND CAST(p.Escritura AS UNSIGNED)=1 LIMIT 1");$s->execute([$q->getAttribute('ali_user')]);return (bool)$s->fetchColumn();
}
function aliKnowledgeProduct($db,$id,$lock=false){$s=$db->prepare('SELECT IdProducto,Producto,ProductoModelo,ProductoDescCorto,ProductoDesc FROM Gen_Producto WHERE IdProducto=? AND Anulado=0'.($lock?' FOR UPDATE':''));$s->execute([$id]);return $s->fetch(PDO::FETCH_ASSOC);}
function aliKnowledgeHash($product){$product['IdProducto']=(int)$product['IdProducto'];return hash('sha256',json_encode($product,JSON_UNESCAPED_UNICODE));}
function aliKnowledgeRead($db,$id){$s=$db->prepare('SELECT * FROM Ali_ProductoFicha WHERE product_id=?');$s->execute([$id]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row)return null;$row['characteristics']=aliCharacteristicText($row['characteristics']);$row['revision']=(int)$row['revision'];$row['sources']=json_decode($row['sources_json'],true)?:[];unset($row['sources_json']);return $row;}
function aliKnowledgeString($p,$key,$max,$required=false){$value=$p[$key]??'';if(!is_string($value)||mb_strlen($value)>$max||($required&&trim($value)===''))throw new InvalidArgumentException('Revisa el campo '.$key.' y su longitud.');return trim($value);}
function aliProductKnowledge($db,$q,$r){
 $p=$q->getParsedBody()?:[];$id=filter_var($p['id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1)return $r->withJson(['error'=>'Selecciona un producto válido.'],422);
 $product=aliKnowledgeProduct($db,$id);if(!$product)return $r->withJson(['error'=>'Producto no disponible.'],404);
 $canEdit=aliKnowledgeCanEdit($db,$q);
 if(($p['mode']??'')==='knowledge_get'){$row=aliKnowledgeRead($db,$id);return $r->withJson(['knowledge'=>$row,'usage'=>aliUsageRead($db,$id),'product'=>$product,'suggested_model'=>aliGuideExactModel($product),'can_edit'=>$canEdit,'catalog_changed'=>$row&&!hash_equals($row['catalog_hash'],aliKnowledgeHash($product))]);}
 if(($p['mode']??'')==='usage_save')return aliUsageSave($db,$q,$r,$id,$canEdit);
 if(!$canEdit)return $r->withJson(['error'=>'Necesitas permiso para operar el punto de venta o editar productos para guardar una ficha compartida.'],403);
 try{$model=aliKnowledgeString($p,'model',200);$text=aliKnowledgeString($p,'characteristics',12000,true);$text=aliCharacteristicText($text);if($text==='')throw new InvalidArgumentException('Incluye características técnicas.');$usedFor=aliKnowledgeString($p,'used_for',4000);$pending=aliKnowledgeString($p,'pending',4000);$reference=aliKnowledgeString($p,'reference',1000);$revision=filter_var($p['revision']??null,FILTER_VALIDATE_INT);if($revision===false||$revision<0||($p['reviewed']??false)!==true)throw new InvalidArgumentException('Revisa las características y confirma la comprobación antes de guardar.');
  $input=$p['sources']??[];if(!is_array($input)||count($input)>20)throw new InvalidArgumentException('Incluye hasta 20 fuentes.');$sources=[];foreach($input as $source){if(!is_array($source)||!aliGuideUrl($source['url']??null)||strlen($source['url'])>2000)throw new InvalidArgumentException('Las fuentes deben ser enlaces HTTP o HTTPS válidos.');$title=aliKnowledgeString($source,'title',300);$sources[$source['url']]=['url'=>$source['url'],'title'=>$title?:$source['url']];}if(!$sources&&$reference==='')throw new InvalidArgumentException('Incluye una fuente o una referencia comprobada, como la etiqueta del producto.');
  $db->beginTransaction();$product=aliKnowledgeProduct($db,$id,true);if(!$product){$db->rollBack();return $r->withJson(['error'=>'Producto no disponible.'],404);}$old=aliKnowledgeRead($db,$id);if(($old?(int)$old['revision']:0)!==$revision){$db->rollBack();return $r->withJson(['error'=>'Otra persona actualizó esta ficha. Cierra y vuelve a abrir antes de guardar.'],409);}
  $sync=$db->prepare('UPDATE Gen_Producto SET ProductoDesc=? WHERE IdProducto=? AND Anulado=0');$sync->execute([$text,$id]);$product['ProductoDesc']=$text;
  $now=(new DateTimeImmutable('now',new DateTimeZone('America/Lima')))->format('Y-m-d H:i:s');$user=(string)$q->getAttribute('ali_user');$data=['model'=>$model,'characteristics'=>$text,'used_for'=>$usedFor,'pending'=>$pending,'reference'=>$reference,'sources'=>array_values($sources),'revision'=>$revision+1,'saved_by'=>$user,'saved_at'=>$now,'catalog_hash'=>aliKnowledgeHash($product)];
  $s=$db->prepare('INSERT INTO Ali_ProductoFicha(product_id,model,characteristics,used_for,pending,reference,sources_json,revision,catalog_hash,saved_by,saved_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE model=VALUES(model),characteristics=VALUES(characteristics),pending=VALUES(pending),reference=VALUES(reference),sources_json=VALUES(sources_json),revision=VALUES(revision),catalog_hash=VALUES(catalog_hash),saved_by=VALUES(saved_by),saved_at=VALUES(saved_at)');$s->execute([$id,$model,$text,$usedFor,$pending,$reference,json_encode($data['sources'],JSON_UNESCAPED_UNICODE),$revision+1,$data['catalog_hash'],$user,$now]);
  $s=$db->prepare('INSERT INTO Ali_ProductoFichaHistorial(product_id,revision,data_json,saved_by,saved_at) VALUES(?,?,?,?,?)');$s->execute([$id,$revision+1,json_encode($data,JSON_UNESCAPED_UNICODE),$user,$now]);$db->commit();return $r->withJson(['knowledge'=>$data,'can_edit'=>true,'catalog_changed'=>false]);
 }catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();return $r->withJson(['error'=>$e->getMessage()],422);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();return $r->withJson(['error'=>'No se pudo guardar la ficha. Intenta nuevamente.'],503);}
}
function aliGuideExactModel($product,$override=''){
 $model=trim($override?:($product['ProductoModelo']??''));$unknown=['','S/M','S-M','SM','SIN MODELO','SIN MARCA','N/A','NA','GENERICO','GENÉRICO','NINGUNO','-'];
 if(!in_array(mb_strtoupper($model),$unknown,true)&&preg_match('/[0-9]/',$model)){if(preg_match('/\b(?=[a-z0-9-]{5,}\b)(?=[a-z0-9-]*[a-z])(?=[a-z0-9-]*[0-9])[a-z0-9]+(?:-[a-z0-9]+)+\b/i',$model,$m))return $m[0];return $model;}
 if(preg_match('/\b(?=[a-z0-9-]{5,}\b)(?=[a-z0-9-]*[a-z])(?=[a-z0-9-]*[0-9])[a-z0-9]+(?:-[a-z0-9]+)+\b/i',$product['Producto']??'',$m))return $m[0];
 return '';
}

function aliUsageRead($db,$id){$s=$db->prepare('SELECT * FROM Ali_ProductoUso WHERE product_id=?');$s->execute([$id]);$row=$s->fetch(PDO::FETCH_ASSOC);if($row)$row['revision']=(int)$row['revision'];return $row?:null;}
function aliUsageSave($db,$q,$r,$id,$canEdit){
 if(!$canEdit)return $r->withJson(['error'=>'No tienes permiso para guardar referencias.'],403);
 try{$p=$q->getParsedBody();$text=aliKnowledgeString($p,'used_for',4000,true);$revision=filter_var($p['revision']??null,FILTER_VALIDATE_INT);if($revision===false||$revision<0)throw new InvalidArgumentException('Revisa la revisión de la referencia.');$db->beginTransaction();aliKnowledgeProduct($db,$id,true);$old=aliUsageRead($db,$id);if(($old?$old['revision']:0)!==$revision){$db->rollBack();return $r->withJson(['error'=>'Otra persona actualizó los usos. Vuelve a abrir la ficha.'],409);}$now=(new DateTimeImmutable('now',new DateTimeZone('America/Lima')))->format('Y-m-d H:i:s');$user=(string)$q->getAttribute('ali_user');$s=$db->prepare('INSERT INTO Ali_ProductoUso(product_id,used_for,revision,saved_by,saved_at) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE used_for=VALUES(used_for),revision=VALUES(revision),saved_by=VALUES(saved_by),saved_at=VALUES(saved_at)');$s->execute([$id,$text,$revision+1,$user,$now]);$db->commit();return $r->withJson(['usage'=>['used_for'=>$text,'revision'=>$revision+1,'saved_by'=>$user,'saved_at'=>$now]]);}catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();return $r->withJson(['error'=>$e->getMessage()],422);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();return $r->withJson(['error'=>'No se pudo guardar la referencia.'],503);}
}
